urllib3.fields._replace_multiple:
def _replace_multiple(value, needles_and_replacements):

    def replacer(match):
        return needles_and_replacements[match.group(0)]
    pattern = re.compile('|'.join([re.escape(needle) for needle in needles_and_replacements.keys()]))
    result = pattern.sub(replacer, value)
    return result

charset_normalizer.utils.is_emoticon:
@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_emoticon(character: str) -> bool:
    character_range: Optional[str] = unicode_range(character)
    if character_range is None:
        return False
    return 'Emoticons' in character_range

charset_normalizer.utils.range_scan:
def range_scan(decoded_sequence: str) -> List[str]:
    ranges: Set[str] = set()
    for character in decoded_sequence:
        character_range: Optional[str] = unicode_range(character)
        if character_range is None:
            continue
        ranges.add(character_range)
    return list(ranges)

requests.utils.unquote_unreserved:
def unquote_unreserved(uri):
    """Un-escape any percent-escape sequences in a URI that are unreserved
    characters. This leaves all reserved, illegal and non-ASCII bytes encoded.

    :rtype: str
    """
    parts = uri.split('%')
    for i in range(1, len(parts)):
        h = parts[i][0:2]
        if (len(h) == 2 and h.isalnum()):
            try:
                c = chr(int(h, 16))
            except ValueError:
                raise InvalidURL(f"Invalid percent-escape sequence: '{h}'")
            if c in UNRESERVED_SET:
                parts[i] = c + parts[i][2:]
            else:
                parts[i] = f'%{parts[i]}'
        else:
            parts[i] = f'%{parts[i]}'
    return ''.join(parts)

requests.utils.requote_uri:
def requote_uri(uri):
    """Re-quote the given URI.

    This function passes the given URI through an unquote/quote cycle to
    ensure that it is fully and consistently quoted.

    :rtype: str
    """
    safe_with_percent = "!#$%&'()*+,/:;=?@[]~"
    safe_without_percent = "!#$&'()*+,/:;=?@[]~"
    try:
        return quote(unquote_unreserved(uri), safe=safe_with_percent)
    except InvalidURL:
        return quote(uri, safe=safe_without_percent)

requests.utils.proxy_bypass_registry:
def proxy_bypass_registry(host):
    try:
        import winreg
    except ImportError:
        return False
    try:
        internetSettings = winreg.OpenKey(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings')
        proxyEnable = int(winreg.QueryValueEx(internetSettings, 'ProxyEnable')[0])
        proxyOverride = winreg.QueryValueEx(internetSettings, 'ProxyOverride')[0]
    except (OSError, ValueError):
        return False
    if (not proxyEnable or not proxyOverride):
        return False
    proxyOverride = proxyOverride.split(';')
    for test in proxyOverride:
        if test == '<local>':
            if '.' not in host:
                return True
        test = test.replace('.', '\\.')
        test = test.replace('*', '.*')
        test = test.replace('?', '.')
        if re.match(test, host, re.I):
            return True
    return False

requests.utils.proxy_bypass:
def proxy_bypass(host):
    """Return True, if the host should be bypassed.

        Checks proxy settings gathered from the environment, if specified,
        or the registry.
        """
    if getproxies_environment():
        return proxy_bypass_environment(host)
    else:
        return proxy_bypass_registry(host)
